import type { Metadata } from 'next'
import { useRouter } from 'next/navigation'
import { headers } from 'next/headers'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

interface Post {
  id: number
  title: string
  body: string
  userId: number
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store',
  })
  return res.json()
}

async function getUserAgent(): Promise<string> {
  const headersList = await headers()
  return headersList.get('user-agent') || ''
}

export default async function HomePage() {
  const [posts, userAgent] = await Promise.all([getPosts(), getUserAgent()])
  const router = useRouter()
  const timestamp = new Date().toISOString()

  const navigateToBlog = () => {
    router.push('/blog')
  }

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <a href={`/blog/${post.id}`}>{post.title}</a>
          </li>
        ))}
      </ul>

      <button onClick={navigateToBlog}>View All Posts</button>
    </div>
  )
}

